#!/usr/bin/env bash
# Deploy-time check for the real nginx boundary. The Flask refresh limiter can also
# return JSON 429s, so require at least one HTML 429 generated by nginx itself.
# mv_refresh_zone drains at about one request per two seconds; its burst self-heals
# in under a minute after this check.
set -euo pipefail

if [[ $# -ne 1 ]]; then
    echo "Usage: $0 https://markervault.example"
    exit 2
fi

mv_base_url=${1%/}
mv_edge_429=0
mv_all_429=0
mv_503=0

for ((mv_request = 1; mv_request <= 35; mv_request++)); do
    mv_result=$(curl --insecure --silent --show-error --output /dev/null \
        --request POST --write-out '%{http_code} %{content_type}' \
        "$mv_base_url/auth/refresh")
    mv_status=${mv_result%% *}
    mv_content_type=${mv_result#* }

    if [[ $mv_status == 429 ]]; then
        mv_all_429=$((mv_all_429 + 1))
        if [[ $mv_content_type == text/html* ]]; then
            mv_edge_429=$((mv_edge_429 + 1))
        fi
    elif [[ $mv_status == 503 ]]; then
        mv_503=$((mv_503 + 1))
    fi
done

echo "Observed $mv_all_429 total 429s ($mv_edge_429 from nginx) and $mv_503 503s"

if [[ $mv_edge_429 -lt 1 || $mv_503 -ne 0 ]]; then
    echo "FAIL: expected at least one nginx-generated 429 and zero 503 responses"
    exit 1
fi

echo "PASS: deployed nginx rate-limit rejections use 429"
